const issuer = 'http://127.0.0.1:18082/realms/bank-customer';
const clientId = 'bank-customer-web';
const redirectUri = `${window.location.origin}/`;
let accessToken = null;
const $ = (id) => document.getElementById(id);
function setStatus(text) { $('status').textContent = text; }
function showError(text) { $('error').textContent = text; $('error').hidden = false; }
function randomString(size = 48) { const bytes = crypto.getRandomValues(new Uint8Array(size)); return btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=/g,''); }
async function challenge(verifier) { const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(verifier)); return btoa(String.fromCharCode(...new Uint8Array(digest))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=/g,''); }
async function login() { const verifier = randomString(); const state = randomString(24); const pkce = await challenge(verifier); sessionStorage.setItem('pkce_verifier', verifier); sessionStorage.setItem('oidc_state', state); const url = new URL(`${issuer}/protocol/openid-connect/auth`); url.search = new URLSearchParams({client_id:clientId,redirect_uri:redirectUri,response_type:'code',scope:'openid profile',state,code_challenge:pkce,code_challenge_method:'S256'}); window.location.assign(url); }
async function exchange() { const params = new URLSearchParams(location.search); const code = params.get('code'); if (!code) return false; if (params.get('state') !== sessionStorage.getItem('oidc_state')) throw new Error('登录状态校验失败'); const body = new URLSearchParams({grant_type:'authorization_code',client_id:clientId,redirect_uri:redirectUri,code,code_verifier:sessionStorage.getItem('pkce_verifier')}); const res = await fetch(`${issuer}/protocol/openid-connect/token`, {method:'POST',he
aders:{'Content-Type':'application/x-www-form-urlencoded'},body}); if (!res.ok) throw new Error('登录交换失败'); accessToken = (await res.json()).access_token; sessionStorage.removeItem('pkce_verifier'); sessionStorage.removeItem('oidc_state'); history.replaceState({},'',redirectUri); return true; }
async function loadAccounts() { const res = await fetch('/api/customer/v1/accounts',{headers:{Authorization:`Bearer ${accessToken}`}}); if (!res.ok) throw new Error(`账户查询失败（${res.status}）`); const data = await res.json(); $('accounts').innerHTML = data.items.length ? data.items.map(a=>`<article class="account"><strong>${a.maskedAccountNumber}</strong><div class="balance">${a.balance} ${a.currency}</div><small>账户编号：${a.accountId}</small></article>`).join('') : '<p>当前客户暂无已关联账户。</p>'; }
async function start() { $('login').addEventListener('click', login); $('logout').addEventListener('click', ()=>{accessToken=null;$('dashboard').hidden=true;$('login-panel').hidden=false;setStatus('已退出');}); try { const exchanged = await exchange(); if (!exchanged) { $('login-panel').hidden=false; setStatus('请登录后查看账户'); return; } $('login-panel').hidden=true; $('dashboard').hidden=false; setStatus('已安全登录'); await loadAccounts(); } catch (e) { showError(e.message); $('login-panel').hidden=false; setStatus('需要重新登录'); } }
start();

