import { useNavigate } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';
import { Card, Col, Row, Button, Typography, Tag, Empty, Skeleton } from 'antd';
import { PageContainer } from '@/components/PageContainer';
import type { PageState } from '@/components/PageContainer';
import { apiClient } from '@/api/client';
import type { AccountListResponse } from '@/types/models';

const { Text } = Typography;

export function AccountList(): JSX.Element {
  const navigate = useNavigate();

  const { data, isLoading, isError } = useQuery<AccountListResponse>({
    queryKey: ['accounts'],
    queryFn: () => apiClient.get<AccountListResponse>('/accounts'),
  });

  const pageState: PageState = isLoading
    ? 'LOADING'
    : isError
      ? 'ERROR'
      : 'READY';

  const accounts = data?.items ?? [];

  return (
    <PageContainer
      pageId="customer.accounts"
      state={pageState}
      title="账户列表"
    >
      <div data-testid="account-list" style={{ padding: '24px' }}>
        {isLoading && <Skeleton active />}

        {!isLoading && isError && (
          <Empty description="加载账户列表失败" data-testid="account-list-error" />
        )}

        {!isLoading && !isError && accounts.length === 0 && (
          <Empty description="暂无账户" data-testid="account-list-empty" />
        )}

        {!isLoading && !isError && accounts.length > 0 && (
          <Button
            type="primary"
            onClick={() => navigate('/transfers/new')}
            style={{ marginTop: 24 }}
            data-testid="account-list-transfer"
          >
            新建转账
          </Button>
        )}
      </div>
    </PageContainer>
  );
}

import { useParams, useNavigate } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';
import {
  Button,
  Card,
  Descriptions,
  Space,
  Table,
  Tag,
  Timeline,
  Typography,
} from 'antd';
import type { ColumnsType } from 'antd/es/table';
import { PageContainer } from '@/components/PageContainer';
import { apiClient, ApiError } from '@/api/client';
import type {
  OutboxEvent,
  TransferDetail,
  TransferStateHistoryEntry,
  TransferStatus,
} from '@/types/models';

const { Text } = Typography;

const statusColorMap: Record<TransferStatus, string> = {
  CREATED: 'default',
  VALIDATING: 'processing',
  RISK_REVIEW: 'warning',
  PENDING_APPROVAL: 'processing',
  PENDING_CORE_POSTING: 'processing',
  PENDING_CLEARING: 'processing',
  SETTLED: 'success',
  FAILED: 'error',
  TIMED_OUT: 'error',
  RETURNED: 'error',
  REVERSAL_PENDING: 'warning',
  REVERSED: 'error',
};

function useTransferDetail(paymentId: string) {
  return useQuery<TransferDetail, ApiError>({
    queryKey: ['transfer-detail', paymentId],
    queryFn: () => apiClient.get<TransferDetail>(`/transfers/${paymentId}`),
  });
}

function StatusTimeline({
  history,
}: {
  history: TransferStateHistoryEntry[];
}): JSX.Element {
  const items = history.map((entry) => ({
    color:
      entry.toStatus === 'SETTLED'
        ? 'green'
        : entry.toStatus === 'FAILED' ||
            entry.toStatus === 'TIMED_OUT' ||
            entry.toStatus === 'REVERSED'
          ? 'red'
          : 'blue',
    children: (
      <div data-testid={`state-history-item-${entry.id}`}>
        <Space direction="vertical" size={0}>
          <Space>
            <Tag color={statusColorMap[entry.toStatus]}>{entry.toStatus}</Tag>
            {entry.fromStatus && (
              <Text type="secondary">from {entry.fromStatus}</Text>
            )}
          </Space>
          <Text type="secondary" style={{ fontSize: 12 }}>
            {entry.actorType}: {entry.actorId} &middot; {entry.createdAt}
          </Text>
          {entry.reasonCode && (
            <Text type="secondary" style={{ fontSize: 12 }}>
              reason: {entry.reasonCode}
            </Text>
          )}
        </Space>
      </div>
    ),
  }));

  return (
    <Timeline
      items={items}
      data-testid="state-history-timeline"
      mode="left"
    />
  );
}

